public sealed class OutboxMessage
{
    public Guid Id { get; set; }
    public string Type { get; set; } = "";
    public string Payload { get; set; } = "";
    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset? ProcessedAt { get; set; }
}

public async Task<Order> PlaceOrderAsync(PlaceOrderCommand cmd, CancellationToken ct)
{
    var order = new Order { Id = Guid.NewGuid(), CustomerId = cmd.CustomerId };
    _db.Orders.Add(order);

    _db.OutboxMessages.Add(new OutboxMessage
    {
        Id = Guid.NewGuid(),
        Type = nameof(OrderPlacedEvent),
        Payload = JsonSerializer.Serialize(new OrderPlacedEvent(order.Id, order.CustomerId)),
        CreatedAt = DateTimeOffset.UtcNow
    });

    await _db.SaveChangesAsync(ct); // single transaction — order + outbox atomic
    return order;
}

public sealed class OutboxDispatcher(
    IServiceScopeFactory scopes,
    ILogger<OutboxDispatcher> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await using var scope = scopes.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var publisher = scope.ServiceProvider.GetRequiredService<IEventPublisher>();

            var batch = await db.OutboxMessages
                .Where(m => m.ProcessedAt == null)
                .OrderBy(m => m.CreatedAt)
                .Take(50)
                .ToListAsync(ct);

            foreach (var msg in batch)
            {
                try
                {
                    await publisher.PublishAsync(msg.Type, msg.Payload, ct);
                    msg.ProcessedAt = DateTimeOffset.UtcNow;
                }
                catch (Exception ex)
                {
                    logger.LogError(ex, "Outbox publish failed {Id}", msg.Id);
                    break; // retry batch on next poll
                }
            }
            if (batch.Count > 0)
                await db.SaveChangesAsync(ct);

            await Task.Delay(TimeSpan.FromSeconds(2), ct);
        }
    }
}

public sealed class SqsEventPublisher(IAmazonSQS sqs, IOptions<SqsOptions> opts) : IEventPublisher
{
    public async Task PublishAsync(string type, string payload, CancellationToken ct)
    {
        await sqs.SendMessageAsync(new SendMessageRequest
        {
            QueueUrl = opts.Value.EventsQueueUrl,
            MessageBody = payload,
            MessageAttributes = new Dictionary<string, MessageAttributeValue>
            {
                ["EventType"] = new() { DataType = "String", StringValue = type }
            }
        }, ct);
    }
}

// RISKY: mark ProcessedAt BEFORE SQS confirms delivery
msg.ProcessedAt = DateTimeOffset.UtcNow;
await db.SaveChangesAsync(ct);
await publisher.PublishAsync(...); // crash here → event lost forever

// SAFER: publish first, then mark processed in same SaveChanges
await publisher.PublishAsync(msg.Type, msg.Payload, ct);
msg.ProcessedAt = DateTimeOffset.UtcNow;
await db.SaveChangesAsync(ct);
// If crash after publish but before SaveChanges → duplicate SQS message
// Downstream must be idempotent — acceptable tradeoff

